CREATE TABLE IF NOT EXISTS clients(id SERIAL PRIMARY KEY,name TEXT NOT NULL,contact TEXT,status TEXT DEFAULT 'ACTIVO',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS projects(id SERIAL PRIMARY KEY,code TEXT UNIQUE NOT NULL,client TEXT NOT NULL,name TEXT NOT NULL,service_type TEXT,stage TEXT DEFAULT 'BRIEF',status TEXT DEFAULT 'PENDIENTE' CHECK(status IN('PENDIENTE','EN_CURSO','COMPLETADO','OBSERVADO')),amount NUMERIC(14,2) DEFAULT 0,closed_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log(id BIGSERIAL PRIMARY KEY,entity TEXT,entity_id TEXT,action TEXT,user_name TEXT,payload JSONB,created_at TIMESTAMPTZ DEFAULT now());